    if (n % 2 == 1) {
        printf("0\n");
        return 0;
    }

    long long ans = 0;

    // Try all possible first pairings for vertex 0 to break symmetry
    for (int first_pair = 1; first_pair < n; first_pair++) {
        if (adj[0][first_pair]) continue; // can't pair if road exists

        // We'll treat range [1, n-1] excluding first_pair
        // Build linear DP: we remove 0 and first_pair from the circle,
        // then treat remaining vertices in cyclic order.

        int used[1000] = {0};
        used[0] = 1;
        used[first_pair] = 1;

        // Build linear ordering
        int order[1000];
        int idx = 0;
        for (int i = 1; i < n; i++) {
            if (!used[i]) order[idx++] = i;
        }
        int len = idx; // should be n-2

        // DP over intervals on this linear array
        for (int i = 0; i < len; i++) {
            for (int j = 0; j < len; j++) {
                dp[i][j] = 0;
            }
        }

        for (int i = 0; i < len; i++) {
            dp[i][i] = 0; // single vertex can't be matched
            if (i+1 < len && !adj[order[i]][order[i+1]]) {
                dp[i][i+1] = 1;
            }
        }

        for (int length = 3; length <= len; length += 2) {
            for (int i = 0; i + length - 1 < len; i++) {
                int j = i + length - 1;
                dp[i][j] = 0;
                // pair order[i] with some k
                for (int k = i+1; k <= j; k += 2) {
                    if (!adj[order[i]][order[k]]) {
                        long long left = (i+1 > k-1) ? 1 : dp[i+1][k-1];
                        long long right = (k+1 > j) ? 1 : dp[k+1][j];
                        dp[i][j] = (dp[i][j] + left * right) % MOD;
                    }
                }
            }
        }

        ans = (ans + dp[0][len-1]) % MOD;
    }

    // Each pairing is counted twice because we could start from either endpoint of the first pair
    // But here we fixed vertex 0 as one endpoint, so no double counting.
    printf("%lld\n", ans % MOD);
    return 0;
}

