#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000003

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    if (n % 2 == 1) {
        /* Perfect pairing impossible for odd number of ports */
        printf("0\n");
        return 0;
    }

    /* bad[i][j] = 1 if i and j cannot be paired as sister ports
       because there is a road between them.
       Polygon boundary roads are also roads, so adjacent vertices are forbidden too.
    */
    unsigned char *bad = (unsigned char *)calloc((size_t)n * n, sizeof(unsigned char));
    if (!bad) return 0;

    #define BAD(i,j) bad[(size_t)(i) * n + (j)]

    /* Adjacent ports on the n-gon */
    for (int i = 0; i < n; ++i) {
        int j = (i + 1) % n;
        BAD(i, j) = BAD(j, i) = 1;
    }

    /* Internal roads */
    for (int k = 0; k < m; ++k) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u; --v; /* assume input is 1-based */
        if (u >= 0 && u < n && v >= 0 && v < n && u != v) {
            BAD(u, v) = BAD(v, u) = 1;
        }
    }

    /* dp[l][r]: number of non-crossing perfect matchings of vertices l..r
       on the polygon chain (inclusive), using only pairs with no road between them.
       Valid only when segment length is even.
    */
    int *dp = (int *)calloc((size_t)n * n, sizeof(int));
    if (!dp) {
        free(bad);
        return 0;
    }

    #define DP(l,r) dp[(size_t)(l) * n + (r)]

    /* Empty interval is handled implicitly in transitions as value 1. */

    for (int len = 2; len <= n; len += 2) {
        for (int l = 0; l + len - 1 < n; ++l) {
            int r = l + len - 1;
            long long ways = 0;

            /* Pair l with k, where k-l is odd so both sides have even size */
            for (int k = l + 1; k <= r; k += 2) {
                if (BAD(l, k)) continue;

                long long leftWays = (k == l + 1) ? 1 : DP(l + 1, k - 1);
                if (leftWays == 0) continue;

                long long rightWays = (k == r) ? 1 : DP(k + 1, r);
                if (rightWays == 0) continue;

                ways += leftWays * rightWays;
                ways %= MOD;
            }

            DP(l, r) = (int)(ways % MOD);
        }
    }

    printf("%d\n", DP(0, n - 1));

    free(dp);
    free(bad);
    return 0;
}

