public class SisterPorts {
    static final int MOD = 1000003;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        boolean[][] forbidden = new boolean[n][n];

        // Adjacent ports in the n-gon are connected by roads
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            forbidden[i][j] = true;
            forbidden[j][i] = true;
        }

        // Internal roads
        for (int i = 0; i < m; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            forbidden[a][b] = true;
            forbidden[b][a] = true;
        }

        // DP over subsets, only for even n
        if (n % 2 != 0) {
            System.out.println(0);
            return;
        }

        int totalMasks = 1 << n;
        long[] dp = new long[totalMasks];
        dp[0] = 1;

        for (int mask = 0; mask < totalMasks; mask++) {
            if (dp[mask] == 0) continue;
            int first = -1;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    first = i;
                    break;
                }
            }
            if (first == -1) continue; // all paired

            for (int j = first + 1; j < n; j++) {
                if ((mask & (1 << j)) == 0 && !forbidden[first][j]) {
                    int newMask = mask | (1 << first) | (1 << j);
                    dp[newMask] = (dp[newMask] + dp[mask]) % MOD;
                }
            }
        }

        System.out.println(dp[totalMasks - 1] % MOD);
    }
}

