        int m = sc.nextInt();
        int MOD = 1000003;

        boolean[][] adj = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            adj[i][(i+1)%n] = true;
            adj[(i+1)%n][i] = true;
        }
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt(), v = sc.nextInt();
            adj[u][v] = true;
            adj[v][u] = true;
        }

        if (n % 2 != 0) { System.out.println(0); return; }

        long[] dp = new long[1 << n];
        dp[0] = 1;

        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[mask] == 0) continue;
            int u = -1;
            for (int i = 0; i < n; i++) if ((mask >> i & 1) == 0) { u = i; break; }
            if (u == -1) continue;
            for (int v = u+1; v < n; v++) {
                if ((mask >> v & 1) == 1) continue;
                if (!adj[u][v]) continue;
                // Check induced: u and v must have no neighbors in mask
                boolean ok = true;
                for (int w = 0; w < n && ok; w++) {
                    if ((mask >> w & 1) == 1) {
                        if (adj[u][w] || adj[v][w]) ok = false;
                    }
                }
                if (ok) {
                    int nmask = mask | (1<<u) | (1<<v);
                    dp[nmask] = (dp[nmask] + dp[mask]) % MOD;
                }
            }
        }

        System.out.println(dp[(1<<n)-1]);
    }
}

