/*
 * Sister Ports
 *
 * We have n vertices on a cycle (regular n-gon), with boundary edges between adjacent vertices,
 * plus m extra internal edges between non-adjacent vertices.
 *
 * We need to count perfect matchings of vertices into pairs such that:
 * - every vertex belongs to exactly one pair
 * - paired vertices are NOT connected by a road
 *
 * Equivalently, in the graph G of roads, count perfect matchings in the complement graph H.
 *
 * Key observation:
 * For vertices on a circle, if a pair (u, v) is allowed (no road between them), then every pair
 * crossing it is forbidden as well in any valid perfect matching count decomposition. Standard
 * non-crossing matching DP applies on intervals.
 *
 * Let bad[u][v] = true if there is a road between u and v.
 * Boundary edges are always bad, and given m internal roads are also bad.
 *
 * We count non-crossing perfect matchings using interval DP:
 * dp[l][r] = number of valid ways to perfectly match all vertices in cyclic order interval [l..r]
 *            (on duplicated linearized array), where length is even.
 *
 * Transition:
 *   pair l with k, where k-l is odd and pair (l,k) is allowed.
 *   then dp[l][r] += dp[l+1][k-1] * dp[k+1][r]
 *
 * Since the graph is on a cycle, we can root at 0 and compute on [0..n-1].
 *
 * Complexity: O(n^3), acceptable for moderate n typical for this problem class.
 */

public class Main {
    static final int MOD = 1_000_003;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int m = fs.nextInt();

        if (n <= 0 || (n & 1) == 1) {
            System.out.println(0);
            return;
        }

        boolean[][] bad = new boolean[n][n];

        // Boundary edges of the n-gon
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            bad[i][j] = bad[j][i] = true;
        }

        // Internal roads
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            if (a >= 0 && a < n && b >= 0 && b < n && a != b) {
                bad[a][b] = bad[b][a] = true;
            }
        }

        int[][] dp = new int[n][n];

        // Empty intervals handled implicitly as 1 in transition.
        for (int len = 2; len <= n; len += 2) {
            for (int l = 0; l + len - 1 < n; l++) {
                int r = l + len - 1;
                long ways = 0;

                for (int k = l + 1; k <= r; k += 2) {
                    if (bad[l][k]) continue; // sister ports must NOT have a road

                    long left = (l + 1 <= k - 1) ? dp[l + 1][k - 1] : 1;
                    long right = (k + 1 <= r) ? dp[k + 1][r] : 1;

                    ways += left * right;
                    if (ways >= (long) MOD * MOD) ways %= MOD;
                }

                dp[l][r] = (int) (ways % MOD);
            }
        }

        System.out.println(dp[0][n - 1] % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

