using namespace std;
const int MOD = 1000003;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    // allowed connections (excluding neighbors)
    vector<vector<bool>> allowed(n, vector<bool>(n, false));
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        if (a > b) swap(a, b);
        if ((b - a) % n != 1 && (a + n - b) % n != 1) {
            allowed[a][b] = allowed[b][a] = true;
        }
    }

    // DP over intervals on line (break the cycle by fixing port 0)
    long long ans = 0;

    // Try matching port 0 with port k (k from 1 to n-1, not neighbor)
    for (int k = 2; k <= n-2; k++) {
        if (!allowed[0][k]) continue;

        // We have two intervals: [1, k-1] and [k+1, n-1]
        // Map them to 0-based indices for DP
        auto solve_interval = [&](int L, int R) -> long long {
            if (L > R) return 1;
            int len = R - L + 1;
            if (len % 2 == 1) return 0;
            vector<vector<long long>> dp(len, vector<long long>(len, 0));
            for (int i = 0; i+1 < len; i++) {
                if (allowed[L+i][L+i+1]) dp[i][i+1] = 1;
            }
            for (int length = 4; length <= len; length += 2) {
                for (int i = 0; i + length - 1 < len; i++) {
                    int j = i + length - 1;
                    // match i with some k
                    for (int k = i+1; k <= j; k += 2) {
                        if (allowed[L+i][L+k]) {
                            long long left = (i+1 <= k-1) ? dp[i+1][k-1] : 1;
                            long long right = (k+1 <= j) ? dp[k+1][j] : 1;
                            dp[i][j] = (dp[i][j] + left * right) % MOD;
                        }
                    }
                }
            }
            return dp[0][len-1];
        };

        long long ways = 1;
        ways = (ways * solve_interval(1, k-1)) % MOD;
        ways = (ways * solve_interval(k+1, n-1)) % MOD;
        ans = (ans + ways) % MOD;
    }

    cout << ans % MOD << "\n";
    return 0;
}

