const int MOD = 1000003;

int main() {
    int n, m;
    cin >> n >> m;

    // Build adjacency for the road graph
    vector<vector<bool>> road(n, vector<bool>(n, false));

    // Polygon edges (adjacent ports)
    for (int i = 0; i < n; i++) {
        road[i][(i+1)%n] = true;
        road[(i+1)%n][i] = true;
    }

    // Internal roads
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        road[u][v] = true;
        road[v][u] = true;
    }

    if (n % 2 != 0) {
        cout << 0 << endl;
        return 0;
    }

    // Bitmask DP for perfect matching in complement graph
    vector<long long> dp(1 << n, 0);
    dp[0] = 1;

    for (int mask = 1; mask < (1 << n); mask++) {
        // Find lowest set bit
        int i = __builtin_ctz(mask);
        // Try to pair i with some j
        for (int j = i+1; j < n; j++) {
            if (mask & (1 << j)) {
                // Check if i and j are NOT connected by a road
                if (!road[i][j]) {
                    int prev_mask = mask ^ (1 << i) ^ (1 << j);
                    dp[mask] = (dp[mask] + dp[prev_mask]) % MOD;
                }
            }
        }
    }

    cout << dp[(1 << n) - 1] << endl;
    return 0;
}

